  col += hsv(uHue1, 0.6, 0.05);
  col *= smoothstep(1.5, 0.2, length(uv * vec2(0.85, 1.0)));
  col *= uIntensity;
  col = col / (1.0 + col * 0.6);
  col += (hash(gl_FragCoord.xy + uSeed * 97.0) - 0.5) * 0.02; // grain also hides banding
